-- A sidecar as the v3.1.0 release actually wrote it: `sqlite3 .dump` of a
-- database produced by running that build's own storage API through a full
-- round, then stamped with the `user_version` it left (`.dump` omits it).
--
-- Version 17 is the last shape a release shipped before the chain-submission
-- lifecycle existed, so this is what a production wallet upgrading to this
-- build most likely holds. It walks every rung the lifecycle table owns:
-- created at 18, rebuilt at 19 and 21, and its proposal bound widened.
--
-- Bundle 0 is a completed round: delegated, proved, cast, confirmed, with its
-- helper share accepted. Bundle 1 stops with its delegation on chain and no
-- vote cast — the state `van_comm_rand` exists for, which an upgrade may never
-- lose. Proposal 3 is deliberately skipped. The persisted helper plan carries
-- an `immediate` marker, which is what the version 19 to 20 rung adopts into
-- `round_immediate_share`.
--
-- Generated, not authored. Do not hand-edit; regenerate from a v3.1.0
-- worktree if the shape a released wallet holds ever needs to change.
PRAGMA user_version = 17;

PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE rounds (
    round_id            TEXT NOT NULL,
    wallet_id           TEXT NOT NULL DEFAULT '',
    network             TEXT NOT NULL CHECK (network IN ('mainnet', 'testnet', 'regtest')),
    snapshot_height     INTEGER NOT NULL,
    ea_pk               BLOB NOT NULL,
    nc_root             BLOB NOT NULL,
    nullifier_imt_root  BLOB NOT NULL,
    session_json        TEXT,
    phase               INTEGER NOT NULL DEFAULT 0,
    created_at          INTEGER NOT NULL,
    bundle_policy_json  TEXT,
    PRIMARY KEY (round_id, wallet_id)
);
